-- Step 1: Create index (run once)
-- Note: The GIN index requires the pg_trgm extension. Run 'CREATE EXTENSION IF NOT EXISTS pg_trgm;' as a superuser if it's not enabled.
CREATE INDEX idx_cast_info_note_gin_trgm ON cast_info USING gin (note gin_trgm_ops);
CREATE INDEX idx_title_production_year ON title(production_year);
CREATE INDEX idx_company_name_country_code ON company_name(country_code);
CREATE INDEX idx_cast_info_movie_id ON cast_info(movie_id);
CREATE INDEX idx_movie_companies_movie_id ON movie_companies(movie_id);

-- Step 2: Run the optimized query
SELECT MIN(chn.name) AS character,
       MIN(t.title) AS movie_with_american_producer
FROM title AS t
JOIN cast_info AS ci ON t.id = ci.movie_id
JOIN movie_companies AS mc ON t.id = mc.movie_id
JOIN char_name AS chn ON chn.id = ci.person_role_id
JOIN role_type AS rt ON rt.id = ci.role_id
JOIN company_name AS cn ON cn.id = mc.company_id
JOIN company_type AS ct ON ct.id = mc.company_type_id
WHERE ci.note LIKE '%(producer)%'
  AND cn.country_code = '[us]'
  AND t.production_year > 1990;
